package com.jobtrack.documents;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.regex.Pattern;

import org.springframework.stereotype.Component;

/**
 * Keeps files in a local folder. Keys are generated by the application, never taken
 * from a user's file name, and are checked so they cannot point outside the folder.
 */
@Component
class LocalDocumentStorage implements DocumentStorage {

	private static final Pattern KEY = Pattern.compile("[a-f0-9-]{36}");

	private final Path directory;

	LocalDocumentStorage(DocumentProperties properties) {
		this.directory = properties.directory().toAbsolutePath().normalize();
	}

	@Override
	public void store(String key, InputStream content) throws IOException {
		Files.createDirectories(this.directory);
		Files.copy(content, resolve(key), StandardCopyOption.REPLACE_EXISTING);
	}

	@Override
	public InputStream open(String key) throws IOException {
		return Files.newInputStream(resolve(key));
	}

	@Override
	public void delete(String key) throws IOException {
		Files.deleteIfExists(resolve(key));
	}

	private Path resolve(String key) {
		if (key == null || !KEY.matcher(key).matches()) {
			throw new IllegalArgumentException("Invalid storage key");
		}
		return this.directory.resolve(key);
	}

}
